import sqlite3, service, os, tempfile
d = tempfile.mkdtemp(); p = os.path.join(d, "t.db")
def conn():
    c = sqlite3.connect(p, timeout=2, isolation_level=None if False else "")
    return c
c1 = conn(); service.setup(c1); service.setup(c1)
c1.execute("INSERT INTO accounts VALUES(?,?)", ("a", 100)); c1.commit()
print(service.capture(c1, "k1", "a", 30))
print(service.capture(conn(), "k1", "a", 30))
for args in [("k1","a",31),("k2","a",500),("k3","zz",1),("k4","a",True),("","a",1)]:
    try: service.capture(c1, *args); print("NO ERR", args)
    except ValueError as e: print("ValueError", args, e)
print(c1.execute("SELECT balance_cents FROM accounts").fetchone())
c2 = conn(); c2.execute("BEGIN IMMEDIATE")
try: service.capture(conn(), "k9", "a", 1)
except sqlite3.OperationalError as e: print("lock timeout:", e)
c2.rollback()
